-- 114: Original BrillaPrep WASSCE Agricultural Science beta questions, part 1.
-- Curriculum-aligned practice content; not official WAEC or NaCCA examination material.
PRAGMA foreign_keys = ON;
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_agric_b001_001', 'topic_was_agric_1_1', 'subj_wassce_agric', 'exam_wassce', 'Which activity belongs to the agricultural value chain rather than only primary production?', 'multiple_choice', '["A. Processing cassava into packaged gari for sale","B. Clearing land without producing anything","C. Leaving harvested cassava exposed to rain","D. Discarding all farm records"]', 'A', 'Agriculture includes production, processing, storage, transport and marketing. Turning cassava into packaged gari adds value and can create employment beyond the farm gate. Therefore the correct answer is A: Processing cassava into packaged gari for sale.', 'easy', 1, 1, 90, 'st_was_agric_1_1', 'Identify', 'AO1', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_agric_b001_002', 'topic_was_agric_1_1', 'subj_wassce_agric', 'exam_wassce', 'A learner says agriculture is suitable only for men. Which response is most evidence-based?', 'multiple_choice', '["A. Only heavy manual work counts as agriculture","B. Agricultural enterprises require diverse skills and are open to every gender","C. Women can participate only in retailing","D. Gender determines whether a person can learn agribusiness"]', 'B', 'Modern agriculture includes science, finance, machinery, marketing and management. Ability, training and access to resources—not gender—determine participation and performance. Therefore the correct answer is B: Agricultural enterprises require diverse skills and are open to every gender.', 'medium', 2, 2, 90, 'st_was_agric_1_1', 'Identify', 'AO2', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_agric_b001_003', 'topic_was_agric_1_1', 'subj_wassce_agric', 'exam_wassce', 'Before starting a tomato enterprise, what should a student entrepreneur investigate first?', 'multiple_choice', '["A. The colour of every competitor’s clothing","B. Only the size of the available hoe","C. Local demand, preferred varieties, prices and likely buyers","D. The number of unrelated shops in another region"]', 'C', 'A market survey identifies customer needs, seasonal prices and sales channels. That evidence guides production scale, variety choice, harvest timing and expected revenue. Therefore the correct answer is C: Local demand, preferred varieties, prices and likely buyers.', 'hard', 1, 1, 90, 'st_was_agric_1_1', 'Identify', 'AO3', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_agric_b001_004', 'topic_was_agric_1_1', 'subj_wassce_agric', 'exam_wassce', 'Why should a small farm keep records of inputs, labour, sales and losses?', 'multiple_choice', '["A. To guarantee that weather will remain favourable","B. To remove every biological risk","C. To replace observation of the farm","D. To calculate performance and make evidence-based enterprise decisions"]', 'D', 'Complete records reveal costs, revenue, profit, mortality and yield trends. Comparing those figures helps the farmer correct waste and plan the next production cycle. Therefore the correct answer is D: To calculate performance and make evidence-based enterprise decisions.', 'easy', 2, 2, 90, 'st_was_agric_1_1', 'Explain', 'AO1', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_agric_b001_005', 'topic_was_agric_1_2', 'subj_wassce_agric', 'exam_wassce', 'How can a soil-moisture sensor improve irrigation management?', 'multiple_choice', '["A. It can trigger watering when measured soil moisture falls below a useful threshold","B. It permanently increases rainfall","C. It identifies crop prices without data","D. It sterilises the soil automatically"]', 'A', 'A moisture sensor supplies field evidence about water availability. Using that reading prevents unnecessary watering while reducing the risk of crop water stress. Therefore the correct answer is A: It can trigger watering when measured soil moisture falls below a useful threshold.', 'medium', 3, 3, 90, 'st_was_agric_1_2', 'Explain', 'AO2', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_agric_b001_006', 'topic_was_agric_1_2', 'subj_wassce_agric', 'exam_wassce', 'What is a key advantage of using GPS guidance for field operations?', 'multiple_choice', '["A. It makes fuel unnecessary","B. It reduces overlapping passes and improves placement accuracy","C. It guarantees that every seed germinates","D. It replaces all machinery maintenance"]', 'B', 'GPS guidance helps an operator follow consistent paths. Fewer overlaps can save seed, fertiliser, fuel and time while improving uniform field coverage. Therefore the correct answer is B: It reduces overlapping passes and improves placement accuracy.', 'hard', 2, 2, 90, 'st_was_agric_1_2', 'Identify', 'AO3', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_agric_b001_007', 'topic_was_agric_1_2', 'subj_wassce_agric', 'exam_wassce', 'Which statement best describes hydroponic crop production?', 'multiple_choice', '["A. Plants grow without light or nutrients","B. Every crop is raised only in seawater","C. Plants receive water and mineral nutrients without relying on field soil","D. Roots are prevented from absorbing dissolved ions"]', 'C', 'Hydroponics supplies roots with a managed nutrient solution and support medium where needed. Light, oxygen, water quality and nutrient concentration still require control. Therefore the correct answer is C: Plants receive water and mineral nutrients without relying on field soil.', 'easy', 1, 1, 90, 'st_was_agric_1_2', 'Identify', 'AO1', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_agric_b001_008', 'topic_was_agric_1_2', 'subj_wassce_agric', 'exam_wassce', 'Why might a farmer use a drone to inspect a large field?', 'multiple_choice', '["A. To diagnose every disease with certainty from one photograph","B. To eliminate the need for agronomic knowledge","C. To change soil texture while flying","D. To locate uneven crop growth or stress for targeted ground checks"]', 'D', 'Aerial images can reveal patterns that are hard to see from the ground. They guide inspection, but findings still need verification before treatment decisions are made. Therefore the correct answer is D: To locate uneven crop growth or stress for targeted ground checks.', 'medium', 2, 2, 90, 'st_was_agric_1_2', 'Explain', 'AO2', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_agric_b001_009', 'topic_was_agric_1_3', 'subj_wassce_agric', 'exam_wassce', 'Which implement is mainly used to turn and loosen soil during primary tillage?', 'multiple_choice', '["A. A plough","B. A knapsack sprayer","C. A milking machine","D. A grain moisture meter"]', 'A', 'A plough cuts, lifts and turns the soil, helping bury residues and prepare land for later operations. Harrows generally perform finer secondary tillage. Therefore the correct answer is A: A plough.', 'hard', 1, 1, 90, 'st_was_agric_1_3', 'Identify', 'AO3', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_agric_b001_010', 'topic_was_agric_1_3', 'subj_wassce_agric', 'exam_wassce', 'Why is planter calibration necessary before sowing a field?', 'multiple_choice', '["A. To increase tractor mass permanently","B. To deliver the intended seed rate and spacing","C. To make all seeds genetically identical","D. To avoid checking seed size"]', 'B', 'Calibration relates machine settings, travel distance and seed output. Checking the result reduces waste and supports a plant population appropriate for the crop. Therefore the correct answer is B: To deliver the intended seed rate and spacing.', 'easy', 3, 3, 90, 'st_was_agric_1_3', 'Explain', 'AO1', 'board_waec');
INSERT OR IGNORE INTO question_content_releases (question_id, batch_id, quality_assurance, release_channel, content_label, source_url, official_exam_board_content, feedback_enabled) SELECT id, 'wassce-agric-beta-001', 'automated_beta', 'beta', 'Original BrillaPrep practice content aligned to Ghana’s published NaCCA Agricultural Science curriculum; not official WAEC or NaCCA examination material.', 'https://nacca.gov.gh/wp-content/uploads/2025/04/Agricultural-Science-Curriculum.pdf', 0, 1 FROM questions WHERE id BETWEEN 'q_was_agric_b001_001' AND 'q_was_agric_b001_010';
